-- Apply with supabase db push. Designed for Supabase PostgreSQL.
create extension if not exists pgcrypto;
create table public.users (id uuid primary key references auth.users on delete cascade, display_name text, created_at timestamptz not null default now());
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 100), created_at timestamptz not null default now());
create table public.organization_members (organization_id uuid references public.organizations on delete cascade, user_id uuid references auth.users on delete cascade, role text not null check(role in ('owner','admin','researcher')), primary key(organization_id,user_id));
create function public.is_member(org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from organization_members where organization_id=org and user_id=auth.uid()) $$;
create function public.create_workspace(workspace_name text) returns uuid language plpgsql security definer set search_path=public as $$
declare org uuid;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if length(trim(workspace_name)) not between 1 and 100 then raise exception 'Invalid workspace name'; end if;
 if exists(select 1 from organization_members where user_id=auth.uid()) then raise exception 'User already has a workspace'; end if;
 insert into organizations(name) values(trim(workspace_name)) returning id into org;
 insert into organization_members values(org,auth.uid(),'owner');
 insert into users(id) values(auth.uid()) on conflict do nothing;
 return org;
end $$;
revoke all on function public.create_workspace(text) from public;
grant execute on function public.create_workspace(text) to authenticated;
create table public.discovery_sources (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, provider text not null, created_at timestamptz default now(), unique(organization_id,provider), unique(organization_id,id));
create table public.discovery_queries (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, name text not null, config jsonb not null, enabled boolean not null default false, interval_hours integer not null check(interval_hours between 1 and 8760), next_run_at timestamptz not null default now(), created_at timestamptz not null default now(), unique(organization_id,id));
create table public.discovered_stores (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, domain text not null check(domain=lower(domain) and domain !~ '[/@:[:space:]]'), name text not null, country text check(country in ('US','GB','CA','AU')), country_evidence text, industry text not null default 'Unknown', source_url text not null, source_provider text not null, shopify_verified boolean not null default false, activity integer check(activity between 0 and 100), contact_url text, researched_at timestamptz default now(), unique(organization_id,domain), unique(organization_id,id));
create table public.business_activity_evidence (id uuid primary key default gen_random_uuid(), organization_id uuid not null, store_id uuid not null, source_url text not null, evidence jsonb not null, observed_at timestamptz default now(), foreign key(organization_id,store_id) references public.discovered_stores(organization_id,id) on delete cascade);
create table public.store_technology_evidence (id uuid primary key default gen_random_uuid(), organization_id uuid not null, store_id uuid not null, vendor text not null, source_url text not null, evidence text not null, observed_at timestamptz default now(), foreign key(organization_id,store_id) references public.discovered_stores(organization_id,id) on delete cascade);
create table public.audit_runs (id uuid primary key default gen_random_uuid(), organization_id uuid not null, store_id uuid not null, status text not null default 'running' check(status in ('running','completed','failed','screened_out')), started_at timestamptz default now(), completed_at timestamptz, error text, summary jsonb, unique(organization_id,id), foreign key(organization_id,store_id) references public.discovered_stores(organization_id,id) on delete cascade);
create table public.audit_pages (id uuid primary key default gen_random_uuid(), organization_id uuid not null, audit_id uuid not null, url text not null, kind text not null, status_code integer, metadata jsonb, observed_at timestamptz default now(), unique(organization_id,id), foreign key(organization_id,audit_id) references public.audit_runs(organization_id,id) on delete cascade);
create table public.audit_metrics (id uuid primary key default gen_random_uuid(), organization_id uuid not null, audit_id uuid not null, url text not null, strategy text not null check(strategy in ('mobile','desktop')), sample integer not null check(sample between 1 and 3), scores jsonb not null, diagnostics jsonb not null, field_data jsonb not null, tested_at timestamptz not null, unique(audit_id,strategy,sample), foreign key(organization_id,audit_id) references public.audit_runs(organization_id,id) on delete cascade);
create table public.audit_findings (id uuid primary key default gen_random_uuid(), organization_id uuid not null, audit_id uuid not null, url text not null, category text not null, title text not null, evidence text not null, severity text not null check(severity in ('high','medium','low')), confidence text not null, recommendation text not null, kind text not null check(kind in ('verified','hypothesis','idea')), created_at timestamptz default now(), unique(organization_id,id), foreign key(organization_id,audit_id) references public.audit_runs(organization_id,id) on delete cascade);
create table public.audit_screenshots (id uuid primary key default gen_random_uuid(), organization_id uuid not null, audit_id uuid not null, page_url text not null, storage_path text not null, viewport jsonb, captured_at timestamptz default now(), foreign key(organization_id,audit_id) references public.audit_runs(organization_id,id) on delete cascade);
create table public.historical_snapshots (id uuid primary key default gen_random_uuid(), organization_id uuid not null, audit_id uuid not null, source_url text not null, snapshot_url text, captured_at timestamptz, comparison_months integer not null, evidence jsonb not null, foreign key(organization_id,audit_id) references public.audit_runs(organization_id,id) on delete cascade);
create table public.ai_recommendations (id uuid primary key default gen_random_uuid(), organization_id uuid not null, audit_id uuid not null, recommendation jsonb not null, model text not null, created_at timestamptz default now(), foreign key(organization_id,audit_id) references public.audit_runs(organization_id,id) on delete cascade);
create table public.contacts (id uuid primary key default gen_random_uuid(), organization_id uuid not null, store_id uuid not null, route text not null, role text, source_url text not null, verified_at timestamptz default now(), unique(organization_id,id), foreign key(organization_id,store_id) references public.discovered_stores(organization_id,id) on delete cascade);
create table public.contact_permission_reviews (id uuid primary key default gen_random_uuid(), organization_id uuid not null, store_id uuid not null, status text not null check(status in ('approved','rejected')), country text not null, rationale text not null, reviewed_by uuid not null references auth.users, reviewed_at timestamptz default now(), expires_at timestamptz not null, foreign key(organization_id,store_id) references public.discovered_stores(organization_id,id) on delete cascade);
create table public.suppression_list (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, domain text not null, reason text not null, created_at timestamptz default now(), unique(organization_id,domain));
create table public.lead_scores (id uuid primary key default gen_random_uuid(), organization_id uuid not null, audit_id uuid not null, store_id uuid not null, technical_seo numeric, performance numeric, desktop numeric, modernization numeric, cro numeric, activity numeric, priority integer not null check(priority between 0 and 100), breakdown jsonb not null, created_at timestamptz default now(), foreign key(organization_id,audit_id) references public.audit_runs(organization_id,id) on delete cascade, foreign key(organization_id,store_id) references public.discovered_stores(organization_id,id) on delete cascade);
create table public.leads (id uuid primary key default gen_random_uuid(), organization_id uuid not null, store_id uuid not null, audit_id uuid not null, stage text not null default 'new' check(stage in ('new','reviewing','qualified','hold','suppressed')), notes text not null default '', owner text not null default '', created_at timestamptz default now(), updated_at timestamptz default now(), unique(organization_id,store_id), unique(organization_id,id), foreign key(organization_id,store_id) references public.discovered_stores(organization_id,id) on delete cascade, foreign key(organization_id,audit_id) references public.audit_runs(organization_id,id) on delete cascade);
create table public.lead_activities (id uuid primary key default gen_random_uuid(), organization_id uuid not null, lead_id uuid not null, actor uuid references auth.users, action text not null, details jsonb, created_at timestamptz default now(), foreign key(organization_id,lead_id) references public.leads(organization_id,id) on delete cascade);
create table public.reports (id uuid primary key default gen_random_uuid(), organization_id uuid not null, audit_id uuid not null, store_id uuid not null, storage_path text not null, created_at timestamptz default now(), foreign key(organization_id,audit_id) references public.audit_runs(organization_id,id) on delete cascade, foreign key(organization_id,store_id) references public.discovered_stores(organization_id,id) on delete cascade);
create table public.automation_jobs (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, type text not null check(type in ('discovery','audit')), dedupe_key text, payload jsonb not null default '{}', status text not null default 'queued' check(status in ('queued','running','completed','failed')), progress integer not null default 0 check(progress between 0 and 100), attempts integer not null default 0, max_attempts integer not null default 3, available_at timestamptz not null default now(), lease_until timestamptz, worker_id uuid, started_at timestamptz, completed_at timestamptz, error text, api_usage jsonb not null default '{}', created_at timestamptz default now());
create unique index unique_active_job on public.automation_jobs(organization_id,dedupe_key) where status in ('queued','running') and dedupe_key is not null;
create index queue_due on public.automation_jobs(available_at) where status='queued';
create table public.app_settings (organization_id uuid primary key references public.organizations on delete cascade, config jsonb not null default '{}');
create table public.api_usage_daily (organization_id uuid not null references public.organizations on delete cascade, day date not null default current_date, units integer not null default 0, primary key(organization_id,day));
create function public.claim_job(worker uuid) returns setof public.automation_jobs language plpgsql security definer set search_path=public as $$ begin
 update automation_jobs set status=case when attempts>=max_attempts then 'failed' else 'queued' end,error='Worker lease expired',worker_id=null,lease_until=null,completed_at=case when attempts>=max_attempts then now() else null end where status='running' and lease_until<now();
 return query update automation_jobs set status='running',worker_id=worker,attempts=attempts+1,lease_until=now()+interval '3 minutes',started_at=now(),completed_at=null where id=(select id from automation_jobs where status='queued' and available_at<=now() and attempts<max_attempts order by available_at for update skip locked limit 1) returning *;
end $$;
create function public.enqueue_due_schedules() returns void language plpgsql security definer set search_path=public as $$ declare q discovery_queries; begin
 for q in select * from discovery_queries where enabled and next_run_at<=now() for update skip locked loop
 insert into automation_jobs(organization_id,type,dedupe_key,payload) values(q.organization_id,'discovery','discovery:'||q.id,jsonb_build_object('query_id',q.id)) on conflict do nothing;
 update discovery_queries set next_run_at=now()+make_interval(hours=>q.interval_hours) where id=q.id;
 end loop;
end $$;
create function public.reserve_api_unit(org uuid,job uuid,provider text,budget integer) returns void language plpgsql security definer set search_path=public as $$ declare n integer; begin
 if not exists(select 1 from automation_jobs where id=job and organization_id=org and status='running') then raise exception 'Job not running'; end if;
 insert into api_usage_daily(organization_id,units) values(org,0) on conflict do nothing;
 update api_usage_daily set units=units+1 where organization_id=org and day=current_date and units<budget returning units into n;
 if n is null then raise exception 'Daily API request budget exhausted'; end if;
 update automation_jobs set api_usage=jsonb_set(api_usage,array[provider],to_jsonb(coalesce((api_usage->>provider)::integer,0)+1)) where id=job;
end $$;
revoke all on function public.claim_job(uuid),public.enqueue_due_schedules(),public.reserve_api_unit(uuid,uuid,text,integer) from public,anon,authenticated;
grant execute on function public.claim_job(uuid),public.enqueue_due_schedules(),public.reserve_api_unit(uuid,uuid,text,integer) to service_role;
-- No direct client mutations: membership, tenant IDs, permission decisions and job payloads are API controlled.
do $$ declare t text; begin
 foreach t in array array['users','organizations','organization_members','discovery_sources','discovery_queries','discovered_stores','business_activity_evidence','store_technology_evidence','historical_snapshots','audit_runs','audit_pages','audit_metrics','audit_findings','audit_screenshots','ai_recommendations','lead_scores','contacts','contact_permission_reviews','suppression_list','leads','lead_activities','reports','automation_jobs','app_settings','api_usage_daily'] loop
 execute format('alter table public.%I enable row level security',t);
 if t='users' then execute 'create policy self_read on public.users for select to authenticated using(id=auth.uid())';
 elsif t='organizations' then execute 'create policy member_read on public.organizations for select to authenticated using(public.is_member(id))';
 else execute format('create policy member_read on public.%I for select to authenticated using(public.is_member(organization_id))',t); end if;
 end loop;
end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('audit-artifacts','audit-artifacts',false,10485760,array['application/pdf','image/png']) on conflict(id) do nothing;
